429	+//  owns the whole tensor; grid-stride over Npow2 when Npow2 > blockDim.x.
430	+//  O(N log^2 N) — a STAGE-1 correctness cost, not a hot path.
431	+template <typename GradT>
432	+__device__ __forceinline__ void sg2_stage_segmented_sort(
433	+    const GradT* __restrict__ grad,   // [N] original order (tensor slice)
434	+    float* __restrict__ keys,         // [Npow2] scratch
435	+    int* __restrict__ idx,            // [Npow2] scratch
