438	+    int N) {
439	+    if (N <= 0) return;
440	+    // Npow2 = smallest power of two >= N.
441	+    int np2 = 1;
442	+    while (np2 < N) np2 <<= 1;
443	+    // Initialize keys/idx. Real elements get (|grad|, i); pad gets (+INF, i) with
444	+    // i>=N so the pad's index tie-break keeps it strictly above any real element
445	+    // sharing +INF (none do — real |g| is finite or NaN; NaN guarded to 0).
446	+    for (int i = threadIdx.x; i < np2; i += blockDim.x) {
447	+        if (i < N) {
