1067	                    // ascending block when (t & k)==0, descending otherwise.
1068	                    const bool ascending = ((t & k) == 0);
1069	                    const float ka = keys[t],   kb = keys[ixj];
1070	                    const int   ia = idx[t],    ib = idx[ixj];
1071	                    // (ka,ia) > (kb,ib) under the (|g|, idx) total order?
1072	                    const bool a_gt_b = (ka > kb) || (ka == kb && ia > ib);
1073	                    // swap so that the pair is in the block's required order.
1074	                    if (a_gt_b == ascending) {
1075	                        keys[t] = kb; keys[ixj] = ka;
1076	                        idx[t]  = ib; idx[ixj]  = ia;
1077	                    }
1078	                }
1079	            }
1080	            __syncthreads();
1081	        }
1082	    }
1083	    // perm[r] = idx[r] for r<N (the first N sorted slots are the real elements,
1084	    // since the +INF pad sorted to the top). Build unsort by scatter (race-free:
1085	    // each sorted row r writes its distinct original slot perm[r]).
1086	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1087	        const int src = idx[r];
1088	        perm[r] = src;
1089	        unsort[src] = r;
1090	    }
1091	    __syncthreads();
1092	}
