1094	// =====================================================================
1095	//  sg2_meta_stages<Dims> — the FULL per-tensor pipeline, CTA-local.
1096	//  Runs S0..S5 for ONE tensor (task id `t`) the calling CTA owns. All
1097	//  intermediates live in this CTA's workspace slice. __syncthreads()
1098	//  separates data-dependent stages WITHIN the CTA (the only coupling is
1099	//  this CTA's own rows; no cross-CTA dependence, hence no grid barrier).
1100	// =====================================================================
1101	// WeightsT is either SG2SmemWeights<Dims> (standalone: weights staged to smem)
1102	// or SG2Weights (composed megakernel: weights read from HBM — the SG2 bundle
1103	// does NOT fit smem alongside the model's DecTcSmem/VitTcSmem, see the launcher).
1104	// Both expose the SAME member names indexed as arrays, so the stage bodies are
1105	// identical. BuildSort=true runs STAGE -1 (in-kernel segmented sort) and consumes
1106	// ws.perm/ws.unsort; BuildSort=false consumes the pre-computed st.perm/st.unsort.
1107	template <typename Dims, typename WeightsT, typename ParamT, typename GradT,
1108	          bool BuildSort = false>
1109	__device__ void sg2_meta_stages(
1110	    const WeightsT& w,
1111	    int tid,                            // task (tensor) index
1112	    const SG2State& st,
1113	    const SG2Scalars& sc,
1114	    ParamT* __restrict__ param_base,    // packed params [total]
1115	    const GradT* __restrict__ grad_base,// packed grads  [total]
1116	    const float* __restrict__ sharp_base,// packed sharpness [total]
1117	    float* __restrict__ ws_base) {      // this CTA's workspace slice
1118	    constexpr int d = Dims::d_model;
1119	    const int N = st.n[tid];
1120	    if (N == 0) return;
1121	    const int64_t off = st.row_off[tid];
1122	    const int Nc = (N + Dims::csa_compress - 1) / Dims::csa_compress;
1123	    const int Nh = (N + Dims::hca_compress - 1) / Dims::hca_compress;
1124	    const int topk = (Dims::csa_topk < Nc) ? Dims::csa_topk : Nc;
1125	    const int topk1 = (topk > 0) ? topk : 1;
1126	
1127	    // Tensor-slice pointers.
1128	    ParamT* param = param_base + off;
1129	    const GradT* grad = grad_base + off;
1130	    const float* sharp = sharp_base + off;
1131	    float* exp_avg = st.exp_avg + off;
1132	    float* exp_avg_sq = st.exp_avg_sq + off;
1133	    float* mu = st.mu + off;
1134	    float* slow = st.slow + off;
1135	    float* gru_state = st.gru_state + off * Dims::gru_hidden;
1136	
1137	    // Workspace (carved for Nmax, used for this N).
1138	    SG2Work<Dims> ws = sg2_carve_ws<Dims>(ws_base, /*Nmax=*/N /*carved per tensor*/);
1139	    // NOTE: we carve at exactly N (not Nmax) so the buffers are tightly packed
1140	    // for THIS tensor — valid because ws_stride(Nmax) >= ws_stride(N). The host
1141	    // sizes the slice for Nmax; carving at N keeps the working set contiguous.
1142	
1143	    // STAGE -1: per-tensor segmented sort (composed path). The standalone path
1144	    // pre-computes perm/unsort host-side; there BuildSort=false skips this and the
1145	    // pointers come from st.perm/st.unsort.
1146	    const int* perm;
1147	    const int* unsort;
1148	    if constexpr (BuildSort) {
1149	        sg2_stage_segmented_sort<GradT>(grad, ws.sort_keys, ws.sort_idx,
1150	                                        ws.perm, ws.unsort, N);  // syncs internally
1151	        perm = ws.perm;
1152	        unsort = ws.unsort;
1153	    } else {
1154	        perm = st.perm + off;
1155	        unsort = st.unsort + off;
1156	    }
1157	
1158	    // S0: input projection + gather sorted features.
1159	    sg2_stage_input_proj_sorted<Dims>(w, grad, sharp, perm, ws.x_sorted, N);
1160	    __syncthreads();
1161	
1162	    // Build g_sorted / s_sorted (per-row scalars in sorted order) into the front
1163	    // of qI's buffer is unsafe (qI needed later); instead recompute from grad on
1164	    // the fly where needed (GRU/PEER read g_sorted[r] = grad[perm[r]]). To keep a
1165	    // single source we materialize them into new_gru-adjacent scratch: reuse the
1166	    // tail of expert_out? Too small. Simplest deterministic choice: store into
1167	    // dedicated columns we already have — qI is [N,rank] (rank>=4), so stash
1168	    // g_sorted in concat[:,0] / s_sorted in concat[:,1] BEFORE concat is used by
1169	    // attention? concat is used by out-proj. To avoid any aliasing we compute
1170	    // g_sorted/s_sorted lazily inside GRU/PEER via grad[perm[r]]. (No buffer.)
1171	
1172	    // S1: CSA context.
1173	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_q_W, ws.q, N);             // q
1174	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_k_W, w.csa_compress_w, ws.c_k, N, Nc);
1175	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_v_W, w.csa_compress_w, ws.c_v, N, Nc);
1176	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_k_W, ws.win_k, N);         // window k
1177	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_v_W, ws.win_v, N);         // window v
1178	    sg2_stage_indexer_q<Dims>(ws.x_sorted, w.csa_idx_DQ, ws.qI, N);
1179	    sg2_stage_indexer_k<Dims>(ws.x_sorted, w.csa_idx_K, w.csa_compress_w, ws.kI, N, Nc);
1180	    __syncthreads();
1181	    sg2_stage_topk<Dims>(ws.qI, ws.kI, ws.sel, N, Nc, topk1);
1182	    __syncthreads();
1183	    sg2_stage_csa_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1184	                                  ws.sel, ws.concat, N, Nc, topk1);
1185	    __syncthreads();
1186	    sg2_stage_out_proj<Dims>(ws.concat, w.csa_out_W, ws.csa_ctx, N);
1187	    __syncthreads();
1188	
1189	    // S2: HCA context (reuse q/c_k/c_v/win_k/win_v/concat scratch).
1190	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_q_W, ws.q, N);
1191	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_k_W, nullptr, ws.c_k, N, Nh);
1192	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_v_W, nullptr, ws.c_v, N, Nh);
1193	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_k_W, ws.win_k, N);
1194	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_v_W, ws.win_v, N);
1195	    __syncthreads();
1196	    sg2_stage_hca_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1197	                                  ws.concat, N, Nh);
1198	    __syncthreads();
1199	    sg2_stage_out_proj<Dims>(ws.concat, w.hca_out_W, ws.hca_ctx, N);
1200	    __syncthreads();
1201	
1202	    // g_sorted/s_sorted are read by GRU+PEER as grad[perm[r]]/sharp[perm[r]].
1203	    // To avoid recomputing the perm gather inside two stages, materialize them
1204	    // once into ws.q[:,0] and ws.q[:,1] (q is free now — attention consumed it).
1205	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1206	        const int src = perm[r];
1207	        float g = static_cast<float>(grad[src]);
1208	        float s = sharp[src];
1209	        if (!isfinite(g)) g = 0.0f;
1210	        if (!isfinite(s)) s = 0.0f;
1211	        ws.q[r * d + 0] = g;   // g_sorted
1212	        ws.q[r * d + 1] = s;   // s_sorted
1213	    }
1214	    __syncthreads();
1215	    // Strided views: g_sorted at stride d offset 0, s_sorted at stride d offset 1.
1216	    // The GRU/PEER stages take contiguous [N] g/s; build them into win_k[:,0]/
1217	    // win_k[:,1] contiguous? Simpler: pass strided access via small wrappers.
1218	    // We instead copy to contiguous front of win_k (free) and win_v (free).
1219	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1220	        ws.win_k[r] = ws.q[r * d + 0];   // g_sorted contiguous
1221	        ws.win_v[r] = ws.q[r * d + 1];   // s_sorted contiguous
1222	    }
1223	    __syncthreads();
1224	    const float* g_sorted = ws.win_k;   // [N]
1225	    const float* s_sorted = ws.win_v;   // [N]
1226	
1227	    // S3: matrix-GRU forward (writes new_gru sorted + persists gru_state).
1228	    sg2_stage_gru<Dims>(w, g_sorted, s_sorted, ws.csa_ctx, ws.hca_ctx,
1229	                        perm, gru_state, ws.new_gru, N);
1230	    __syncthreads();
1231	
1232	    // S4: PEER routing + experts → expert_out (sorted), scaled by rescale.
1233	    sg2_stage_peer<Dims>(w, ws.new_gru, ws.csa_ctx, ws.hca_ctx,
1234	                         g_sorted, s_sorted, ws.expert_out, sc.rescale, N);
1235	    __syncthreads();
1236	
1237	    // S5: unsort + sg2_apply_step (canonical math).
1238	    sg2_stage_apply<Dims>(
1239	        param, exp_avg, exp_avg_sq, mu, slow, grad, ws.expert_out, unsort,
1240	        sc.alpha[tid], sc.gru_decay[tid], sc.lamb_eff[tid],
1241	        sc.lr, sc.beta1[tid], sc.beta2, sc.eps, sc.wd,
1242	        sc.bc1[tid], sc.bc2[tid], N);
1243	    __syncthreads();
1244	}
