1246	// =====================================================================
1247	//  The persistent megakernel: ONE launch runs the SG2 optimizer step for
1248	//  ALL parameter tensors. gridDim.x = #SMs, 256 thr/CTA. Each CTA pulls
1249	//  WHOLE tensors from the task queue and runs sg2_meta_stages for each.
1250	//  ONE grid barrier at the end (so a composing model stage can reset the
1251	//  queue). The weight bundle is staged into smem ONCE per CTA up front.
1252	// =====================================================================
1253	// SG_TUNED_MEGA_BLOCK — unified with the fused megakernel's block-thread dim
1254	// (csrc/fused/sm_90/fused_megakernel.cuh). Default 256 (byte-identical untuned
1255	// build). NEEDS-PARITY before shipping a non-default winner (per-head PEER
1256	// routing + scan tiling assume the 256-thread shape).
1257	#ifndef SG_TUNED_MEGA_BLOCK
1258	#define SG_TUNED_MEGA_BLOCK 256
1259	#endif
1260	
1261	template <typename Dims, typename ParamT, typename GradT>
1262	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
1263	sg2_meta_optimizer_megakernel(
1264	    PersistentContext ctx,
1265	    SG2Weights w,
1266	    SG2State st,
1267	    SG2Scalars sc,
1268	    ParamT* __restrict__ params,
1269	    const GradT* __restrict__ grads,
1270	    const float* __restrict__ sharpness) {
1271	    // Stage the (small) weight bundle into shared memory once per CTA.
1272	    __shared__ SG2SmemWeights<Dims> sw;
1273	    sg2_stage_weights<Dims>(sw, w);
1274	    __syncthreads();
1275	
1276	    GridBarrier bar = ctx.barrier();
1277	    float* my_ws = st.workspace + (int64_t)blockIdx.x * st.ws_stride;
1278	
1279	    // Work-steal WHOLE tensors. Each tensor's full pipeline is CTA-local.
1280	    __shared__ int task_slot;
1281	    TaskQueue q = ctx.queue();
1282	    for (int t = q.next_block(&task_slot); t < st.n_tensors;
1283	         t = q.next_block(&task_slot)) {
1284	        sg2_meta_stages<Dims, SG2SmemWeights<Dims>, ParamT, GradT,
1285	                        /*BuildSort=*/false>(
1286	            sw, t, st, sc, params, grads, sharpness, my_ws);
1287	    }
1288	
1289	    // ONE grid barrier: lets a composing model stage reset the queue after the
1290	    // optimizer tail drains. (Standalone, this is just a clean exit fence.)
1291	    bar.sync();
1292	}
1293	
1294	// =====================================================================
1295	//  Host launcher — one persistent CTA per SM, SG_TUNED_MEGA_BLOCK thr/CTA.
1296	//  Mirrors launch_fused_decoder_megakernel's hang-freedom contract:
1297	//  occupancy>=1 or refuse (the GridBarrier rendezvous of n_ctas CTAs can
1298	//  never complete if a CTA cannot be placed). Zeroes the barrier+queue
1299	//  counters per launch. The caller allocates the workspace + index buffers
1300	//  and PRE-COMPUTES perm/unsort (the one explicit pre-kernel sort step).
1301	// =====================================================================
1302	template <typename Dims, typename ParamT, typename GradT>
1303	cudaError_t launch_sg2_meta_optimizer_tail(
1304	    PersistentContext ctx,
1305	    SG2Weights w, SG2State st, SG2Scalars sc,
1306	    ParamT* params, const GradT* grads, const float* sharpness,
1307	    cudaStream_t stream) {
1308	    int dev = 0;
1309	    cudaError_t err = cudaGetDevice(&dev);
1310	    if (err != cudaSuccess) return err;
1311	    int n_sms = 0;
1312	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1313	    if (err != cudaSuccess) return err;
1314	
1315	    int occ = 0;
1316	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1317	        &occ, (const void*)&sg2_meta_optimizer_megakernel<Dims, ParamT, GradT>,
1318	        SG_TUNED_MEGA_BLOCK, /*dynamicSMemBytes=*/0);
1319	    if (err != cudaSuccess) return err;
1320	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1321	
1322	    const unsigned launch_ctas = (unsigned)n_sms;
1323	    ctx.n_ctas = launch_ctas;
1324	    ctx.n_tasks = st.n_tensors;
1325	
1326	    if (ctx.g_arrived)   { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1327	    if (ctx.g_generation){ err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1328	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1329	
1330	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
1331	    sg2_meta_optimizer_megakernel<Dims, ParamT, GradT><<<grid, block, 0, stream>>>(
1332	        ctx, w, st, sc, params, grads, sharpness);
1333	    return cudaGetLastError();
1334	}
